{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "A weighting parameter that linearly combines model-based and model-free Q-values at Stage 1.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "stage1_outcome_perseveration",
      "title": "Stage 1 Outcome-Dependent Perseveration",
      "description": "Adds a bonus to the Stage 1 action value of the previously chosen action, with different magnitudes depending on whether the previous trial was rewarded or unrewarded.",
      "params": [
        {
          "name": "p_stage1_rew",
          "bounds": [-5, 5]
        },
        {
          "name": "p_stage1_unrew",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "if last_a1 != -1 and last_r != -1:\n            if last_r == 1:\n                val_1[last_a1] += p_stage1_rew\n            else:\n                val_1[last_a1] += p_stage1_unrew",
      "expressible_in_slots": true
    },
    {
      "name": "stage2_outcome_perseveration",
      "title": "Stage 2 Outcome-Dependent Perseveration",
      "description": "Adds a bonus to the Stage 2 action value of the previously chosen action if the same state is visited, with different magnitudes depending on whether the previous trial was rewarded or unrewarded.",
      "params": [
        {
          "name": "p_stage2_rew",
          "bounds": [-5, 5]
        },
        {
          "name": "p_stage2_unrew",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "if last_s == s and last_a2 != -1 and last_r != -1:\n            if last_r == 1:\n                val_2[last_a2] += p_stage2_rew\n            else:\n                val_2[last_a2] += p_stage2_unrew",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the Stage 1 model-free Q-value using the Stage 2 reward prediction error, scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[a1] += learning_rate * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "q_init_05",
      "title": "Q-value Initialization at 0.5",
      "description": "Initializes model-free Q-values for both stages at 0.5 instead of 0.",
      "params": [],
      "evidence": "q_stage1_mf = np.full(2, 0.5)\n    q_stage2_mf = np.full((2, 2), 0.5)",
      "expressible_in_slots": true
    }
  ]
}
